from google.cloud import speech_v1p1beta1 as speech

def streaming_recognize_request(config, audio):
    client = speech.SpeechClient()
    streaming_config = speech.StreamingRecognitionConfig(config=config, interim_results=True)
    requests = (speech.StreamingRecognizeRequest(audio_content=audio), speech.StreamingRecognizeRequest(streaming_config=streaming_config))
    return client.streaming_recognize(requests=requests)

def streaming_recognize_response(response):
    for result in response.results:
        if not result.is_final:
            continue
        transcript = result.alternatives[0].transcript
        return transcript

def normalize_transcript(transcript):
    return transcript.lower().strip()

from google.cloud import speech_v1p1beta1 as speech

def streaming_recognize(language_code='en-US'):
    config = {"encoding": speech.enums.RecognitionConfig.AudioEncoding.LINEAR16,
              "sample_rate_hertz": 16000,
              "language_code": language_code,
              "max_alternatives": 1,
              "enable_automatic_punctuation": True}
    client = speech.SpeechClient()
    streaming_config = {"config": config,
                         "interim_results": True}
    requests = (speech.StreamingRecognizeRequest(audio_content=content,
                                                 streaming_config=streaming_config)
                for content in iter(lambda: client.streaming_recognize(streaming_config).result(), None))
    for response in client.streaming_recognize(requests):
        for result in response.results:
            print('Transcript: {}'.format(result.alternatives[0].transcript))

if __name__ == '__main__':
    streaming_recognize()

from google.cloud import speech_v1p1beta1 as speech

def stream_with_language():
    config = {"encoding": "LINEAR16",
             "sample_rate_hertz": 16000,
             "language_code": "en-US",
             "enable_automatic_punctuation": True}
    client = speech.SpeechClient()
    with open('audio.raw', 'rb') as audio_file:
        audio = client.streaming_recognize(config=config,
                                          audio=audio_file)
        for response in audio:
            for result in response.results:
                print(result.alternatives[0].transcript)

if __name__ == '__main__':
    stream_with_language()

import os
from google.cloud import speech_v1p1beta1 as speech

def handle_streaming_recognition(response):
    if response.results:
        for result in response.results:
            if result.is_final:
                print(f"Final result: {result.alternatives[0].transcript}")
            else:
                print(f"Partial result: {result.alternatives[0].transcript}")

# Example usage
client = speech.SpeechClient()
config = speech.RecognitionConfig(
    encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
    sample_rate_hertz=16000,
    language_code="en-US",
)
streaming_config = speech.StreamingRecognitionConfig(config=config)

# Simulate streaming recognition response
response = speech.StreamingRecognizeResponse(
    results=[
        speech.StreamingRecognitionResult(
            is_final=False,
            alternatives=[speech.SpeechRecognitionAlternative(transcript="Hello")],
        ),
        speech.StreamingRecognitionResult(
            is_final=True,
            alternatives=[speech.SpeechRecognitionAlternative(transcript="Hello world!")],
        ),
    ]
)

handle_streaming_recognition(response)
